-- Synthetic disposable fixture ONLY, never a migration for an existing database.
CREATE TABLE FB_USUARIOS (
 USER_ID CHAR(36) PRIMARY KEY,
 USERNAME VARCHAR(100) NOT NULL,
 FIRST_NAME VARCHAR(100) NULL,
 LAST_NAME VARCHAR(100) NULL,
 EMAIL VARCHAR(254) NULL,
 CI VARCHAR(8) NULL,
 USERNAME_KEY VARBINARY(400) NULL UNIQUE,
 EMAIL_KEY VARBINARY(1016) NULL UNIQUE,
 ROLE VARCHAR(30) NOT NULL DEFAULT 'atencion_publico',
 ENABLED TINYINT(1) NOT NULL DEFAULT 1,
 MUST_CHANGE_PASSWORD TINYINT(1) NOT NULL DEFAULT 0,
 PASSWORD_CHANGED_AT DATETIME(6) NULL,
 ADMIN_REVISION BIGINT UNSIGNED NOT NULL DEFAULT 1,
 DELETED_AT DATETIME(6) NULL,
 CONSTRAINT CHK_FB_USUARIOS_ROLE CHECK(ROLE IN ('atencion_publico','collaborator','administrator'))
) ENGINE=InnoDB;
CREATE TABLE FB_USUARIOS_CREDENCIALES (
 USER_ID CHAR(36) PRIMARY KEY,
 PASSWORD_HASH VARCHAR(255) NOT NULL,
 CREATED_AT DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PASSWORD_UPDATED_AT DATETIME(6) NULL,
 FOREIGN KEY(USER_ID) REFERENCES FB_USUARIOS(USER_ID)
) ENGINE=InnoDB;
CREATE TABLE FB_USUARIOS_SESIONES (
 SESSION_ID CHAR(36) PRIMARY KEY,
 USER_ID CHAR(36) NOT NULL,
 TOKEN_HASH CHAR(64) NOT NULL UNIQUE,
 CREATED_AT DATETIME(6) NOT NULL,
 LAST_ACTIVITY_AT DATETIME(6) NOT NULL,
 EXPIRES_AT DATETIME(6) NOT NULL,
 REVOKED_AT DATETIME(6) NULL,
 FOREIGN KEY(USER_ID) REFERENCES FB_USUARIOS(USER_ID)
) ENGINE=InnoDB;
CREATE TABLE TP_ADMIN_AUDIT_V1 (
 EVENT_ID CHAR(36) PRIMARY KEY,
 ACTOR_ID VARCHAR(100) NOT NULL,
 TARGET_ID CHAR(36) NULL,
 ACTOR_USERNAME VARCHAR(100) NULL,
 TARGET_USERNAME VARCHAR(100) NULL,
 ACTION VARCHAR(30) NOT NULL,
 RESULT VARCHAR(10) NOT NULL,
 OCCURRED_AT DATETIME(6) NOT NULL,
 REASON VARCHAR(500) NOT NULL,
 REQUEST_ID VARCHAR(100) NOT NULL,
 ERROR_CODE VARCHAR(100) NULL,
 BEFORE_JSON LONGTEXT NULL,
 AFTER_JSON LONGTEXT NULL,
 CONSTRAINT CHK_TP_ADMIN_AUDIT_ACTION CHECK(ACTION IN ('create','update','reset-password','list','delete','audit-list')),
 CONSTRAINT CHK_TP_ADMIN_AUDIT_RESULT CHECK(RESULT IN ('success','denied')),
 CONSTRAINT CHK_TP_ADMIN_AUDIT_BEFORE CHECK(BEFORE_JSON IS NULL OR JSON_VALID(BEFORE_JSON)),
 CONSTRAINT CHK_TP_ADMIN_AUDIT_AFTER CHECK(AFTER_JSON IS NULL OR JSON_VALID(AFTER_JSON)),
 INDEX IX_TP_ADMIN_AUDIT_TIME(OCCURRED_AT,EVENT_ID)
) ENGINE=InnoDB COMMENT='territorio-paysandu admin-audit-v1';
